"""Load executable negotiation guidance from the installed package, independent of cwd."""

import hashlib
import json
import math
import re
from dataclasses import dataclass
from importlib.resources import files


@dataclass(frozen=True)
class RuntimeGuidance:
    settings: dict
    sha256: str

    @classmethod
    def load(cls):
        raw = files("negotiator").joinpath("AGENTS.md").read_bytes()
        blocks = re.findall(r"^```runtime-settings\s*\n(.*?)^```\s*$", raw.decode(), re.M | re.S)
        if len(blocks) != 1:
            raise ValueError("runtime AGENTS.md requires exactly one runtime-settings block")
        settings = json.loads(blocks[0])
        expected = {"version", "anchor", "rounds", "close_gap", "final_hold_s", "p_walk", "conditional_exchange"}
        if not isinstance(settings, dict) or set(settings) != expected:
            raise ValueError("invalid runtime guidance fields")
        if type(settings["version"]) is not int or settings["version"] != 1:
            raise ValueError("unsupported runtime guidance version")
        if type(settings["rounds"]) is not int or not 1 <= settings["rounds"] <= 100:
            raise ValueError("runtime rounds must be an integer between 1 and 100")
        if type(settings["conditional_exchange"]) is not bool:
            raise ValueError("conditional_exchange must be boolean")
        for key, low, high in (
            ("anchor", 0, 1), ("close_gap", 0, 1), ("p_walk", 0, 1), ("final_hold_s", 0, 3600),
        ):
            value = settings[key]
            if type(value) not in (int, float) or not math.isfinite(value) or not low <= value < high:
                raise ValueError(f"invalid runtime {key}")
        return cls(settings, hashlib.sha256(raw).hexdigest())

    def new_agent(self, *, tracer=None, policy=None):
        from .agent import PackageAgent

        agent = PackageAgent(tracer=tracer, policy=policy, **{
            k: v for k, v in self.settings.items() if k not in ("version", "conditional_exchange")
        })
        agent.conditional_exchange = self.settings["conditional_exchange"]
        agent.runtime_guidance = self.record()
        return agent

    def record(self):
        return {"resource": "negotiator/AGENTS.md", "sha256": self.sha256, "settings": dict(self.settings)}
"""negotiator play <case> | run --set practice|sandbox|final | prep | report <run_dir>"""

import argparse
import json
import logging
import os
import statistics
import sys
import time
from pathlib import Path

from arena_kit.cli import load_env, summary
from arena_kit.client import ArenaClient, ArenaError
from arena_kit.play import RemoteTable, hosted

from .guidance import RuntimeGuidance
from .play import play_all, play_case, play_waves, run_config
from .runner import run_async, runtime_config
from .trace import Tracer


def _run_dir() -> Path:
    root = Path(os.environ.get("NEGOTIATOR_LOG_DIR", "experiments/runs"))
    return root / time.strftime("%Y%m%d-%H%M%S")


def main(argv=None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if argv and argv[0] == "lab":
        from .lab.cli import main as lab_main

        return lab_main(argv[1:])
    if argv and argv[0] == "loop":
        from .lab.loop_cli import main as loop_main

        return loop_main(argv[1:])
    load_env()
    ap = argparse.ArgumentParser(prog="negotiator")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("prep", help="build dossiers and the claim bank from the data package")
    p = sub.add_parser("play", help="play one case")
    p.add_argument("case_id")
    p.add_argument("-v", "--verbose", action="store_true")
    r = sub.add_parser("run", help="play a set; --set final runs the Live Final waves")
    r.add_argument("--set", dest="set_", choices=["practice", "sandbox", "final"], required=True)
    r.add_argument("--parallel", type=int, default=8)
    r.add_argument("--waves", type=int, default=5)
    r.add_argument("-v", "--verbose", action="store_true")
    for sp in (p, r):
        sp.add_argument("--policy-config", help="versioned JSON experiment policy")
        sp.add_argument("--runner", choices=["serial", "async"], default="serial")
    rep = sub.add_parser("report", help="summarise a run directory")
    rep.add_argument("run_dir")
    rep.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)

    if args.cmd == "report":
        from .report import main as report_main

        return report_main([args.run_dir, *(["--json"] if args.json else [])])
    if args.cmd == "prep":
        from .claims import prep

        print(json.dumps(prep()))
        return 0

    logging.basicConfig(
        level=logging.INFO if args.verbose else logging.WARNING, format="%(asctime)s %(message)s", datefmt="%H:%M:%S"
    )
    run_dir = _run_dir()
    tracer = Tracer(run_dir)
    client = ArenaClient()

    from .policy import PolicyConfig

    try:
        guidance = RuntimeGuidance.load()
        policy = PolicyConfig.load(args.policy_config) if args.policy_config else None
    except (OSError, ValueError, TypeError) as exc:
        ap.error(str(exc))

    def new_agent():
        return guidance.new_agent(tracer=tracer, policy=policy)

    if args.runner == "async":
        cfg = {**run_config(new_agent(), runner="async"), **runtime_config(getattr(args, "parallel", 1))}
    else:
        cfg = run_config(new_agent())
    tracer.log("run", cmd=args.cmd, arena=os.environ.get("ARENA_URL"), **cfg)

    if args.runner == "async":
        out = run_async(args, new_agent, tracer, run_dir)
    elif args.cmd == "play":
        table = RemoteTable(client)
        try:
            out = {args.case_id: play_case(table, args.case_id, new_agent())}
        except ArenaError as e:
            raise SystemExit(str(e)) from None
    elif args.set_ == "final":
        out = play_waves(client, new_agent, args.waves, min(args.parallel, 10))
    else:
        ids = [c["case_id"] for c in hosted(client.cases(args.set_))]
        out = play_all(lambda: RemoteTable(client), ids, new_agent, min(args.parallel, 10))

    scores = {}
    for case_id, result in out.items():
        row = repr(result) if isinstance(result, Exception) else summary(result)
        full = None if isinstance(result, Exception) else result  # keeps cost_breakdown
        tracer.log("result", case=case_id, result=row, full=full)
        print(case_id, json.dumps(row))
        if isinstance(result, dict) and result.get("score") is not None:
            scores[case_id] = result["score"]
    if scores:
        print(f"mean score: {100 * statistics.mean(scores.values()):.1f} over {len(scores)}/{len(out)} cases")
    print(f"trace: {tracer.path}")
    if client.practice_remaining is not None:
        print(f"practice sessions left: {client.practice_remaining}")
    return (
        0
        if out
        and all(
            isinstance(r, dict)
            and r.get("score") is not None
            and isinstance(r.get("deal"), bool)
            and r.get("ended", True) is True
            for r in out.values()
        )
        else 1
    )


if __name__ == "__main__":
    raise SystemExit(main())
"""Serial play loop: `arena_kit.play.play` with our evaluator on the deadline path.

The kit loop closes near a wave's cap with its own `closing_move` (first sheet only, no supplier
estimates). `play_case` closes through `evaluator.close_decision` with the agent's estimates.
`play_all` and `play_waves` mirror the kit's but run `play_case`.
"""

import functools
import hashlib
import logging
import os
import subprocess
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from arena_kit.client import ArenaError
from arena_kit.play import (
    CLOSE_BEFORE_CAP_S,
    MOVE_LIMIT_S,
    ROUND_MARGIN_S,
    RemoteTable,
    fetch_documents,
    live_threads,
    quota_used_up,
    standing,
)

from .evaluator import close_decision

log = logging.getLogger("negotiator")


def run_config(agent, runner="serial-play_case", facts="data/package/facts.json"):
    """What a run must record to be comparable: commit, agent params, estimates, runner, data."""
    root = Path(__file__).resolve().parents[2]
    try:
        commit = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"], cwd=root, capture_output=True, text=True, check=True
        ).stdout.strip()
        dirty = bool(
            subprocess.run(
                ["git", "status", "--porcelain", "--", "src"], cwd=root, capture_output=True, text=True
            ).stdout.strip()
        )
    except (OSError, subprocess.CalledProcessError):
        commit, dirty = None, None
    path = Path(os.environ.get("ARENA_DATA", root / Path(facts).parent)) / "facts.json"
    provenance = {}
    try:
        from .dossiers import load_package

        package = load_package()
        for label, directory in [("base", package.root), ("release", package.release)]:
            if directory:
                paths = (
                    sorted(directory.rglob("*"))
                    if label == "release"
                    else [directory / "facts.json", directory / "world.sqlite"]
                )
                provenance[label] = {
                    "path": str(directory),
                    "files": {
                        str(p.relative_to(directory)): hashlib.sha256(p.read_bytes()).hexdigest()
                        for p in paths
                        if p.is_file()
                    },
                }
    except (OSError, ValueError):
        provenance["unavailable"] = True
    data = hashlib.sha256(path.read_bytes()).hexdigest()[:12] if path.exists() else None
    keys = ("anchor", "rounds", "close_gap", "final_hold_s", "meso", "p_walk", "claims")
    params = {k: getattr(agent, k) for k in keys if hasattr(agent, k)}
    return {
        "commit": commit,
        "src_dirty": dirty,
        "agent": getattr(agent, "version", type(agent).__name__),
        "params": params,
        "estimates": (
            "dossiers"
            if getattr(agent, "_estimates", {}) is None
            else "injected"
            if getattr(agent, "_estimates", None)
            else "off"
        ),
        "runner": runner,
        "facts_sha256": data,
        "data_provenance": provenance,
        "policy": agent.policy.record() if getattr(agent, "policy", None) else None,
        "runtime_guidance": getattr(agent, "runtime_guidance", None),
    }


def agent_estimates(agent, case):
    """The agent's supplier estimates for this case ({supplier_id: estimate}), if it has any."""
    if hasattr(agent, "estimates_for"):
        return agent.estimates_for(case)
    return getattr(agent, "estimates", None)


def play_case(table, case_id, agent, deadline=None):
    """Play one case to its end. `deadline` (time.time(), or a function returning it): a Live Final
    wave's cap - shortly before it, `close_decision` closes the case."""
    case, threads = table.open(case_id)
    if (tracer := getattr(agent, "tracer", None)) and getattr(table, "session_id", None):
        base = os.environ.get("ARENA_URL", "").rstrip("/")
        replay = f"{base}/replay/{table.session_id}"
        tracer.log("session", session_id=table.session_id, case_id=case_id, replay_url=replay)
    if getattr(table, "done", None):
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    slowest = 0.0
    while live_threads(threads):
        t0 = time.monotonic()
        if getattr(agent, "trades", None):
            for sid in live_threads(threads):
                agent.trades.deadlines[sid] = time.time() + MOVE_LIMIT_S
        cap = deadline() if callable(deadline) else deadline
        if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S):
            log.info("%s: the wave's cap is near - closing", case_id)
            decision = close_decision(case, threads, agent_estimates(agent, case), "deadline")
            if hasattr(agent, "log_close"):
                agent.log_close(case, threads, decision, "deadline")
        else:
            decision = agent.decide(case, threads)
        if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
            log.warning("decision took %.1fs - the limit is %ss per message", took, MOVE_LIMIT_S)
        sid, msg = decision["supplier_id"], decision["message"]
        try:
            if msg.get("action"):
                log.info("%s %s", sid, msg["action"])
                return table.close(sid, msg)
            reply = table.send(sid, msg)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)
            if msg.get("action") and "result" not in reply:
                threads[sid].append(fetch_documents(table, reply))
                continue
        if "result" in reply:
            return reply["result"]
        if tracer:
            tracer.log("supplier_reply", case=case_id, supplier=sid, message=reply)
        threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
        slowest = max(slowest, time.monotonic() - t0)
        log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
    return table.result()


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Many cases at once, each with its own table and agent; stops starting cases once the
    practice quota is used up. {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play_case(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final (kit `play_waves` structure): play each wave's cases within its cap."""
    started, closed, caps = {}, set(), {}

    def one(case, deadline):
        try:
            return play_case(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}

"""Versioned JSON coding-agent interface for checkpoints, campaigns and recommendations."""

import argparse
import getpass
import json
import os
import uuid
from pathlib import Path

from arena_kit.cli import load_env

from .campaign import arena_snapshot, campaign_dir, reconcile_attempt, run_campaign, sync_campaign
from .checkpoints import _save, create_checkpoint, load_checkpoint, publish_checkpoint, restore_checkpoint
from .loop_client import LoopClient, LoopError
from .policy import default_suite, evaluate_campaign


class Parser(argparse.ArgumentParser):
    def error(self, message):
        raise ValueError("invalid command arguments")


def _shared(parser):
    parser.add_argument("--url", default=os.environ.get("LAB_URL"))
    parser.add_argument("--repo", type=Path, default=Path.cwd())
    parser.add_argument("--root", type=Path, default=Path("experiments/loop"))
    parser.add_argument("--author", default=os.environ.get("LAB_AUTHOR") or getpass.getuser())
    parser.add_argument("--format", choices=("json", "markdown"), default="json")


def add_loop_commands(subparsers):
    loop = subparsers.add_parser("loop", help="immutable checkpoints and executable local campaigns")
    configure(loop)
    return loop


def configure(parser=None, *, groups=None):
    if groups is None:
        groups = parser.add_subparsers(dest="loop_group", required=True)
    for group, commands in {
        "checkpoint": ("create", "publish", "show"),
        "suite": ("list", "show", "create"),
        "family": ("create", "show"),
        "recommended": ("seed", "show", "history", "restore"),
        "campaign": ("run", "status", "compare", "sync", "reconcile"),
        "evidence": ("show",),
        "findings": ("add", "list"),
    }.items():
        parent = groups.add_parser(group)
        parent.set_defaults(loop_group=group)
        sub = parent.add_subparsers(dest="loop_action", required=True)
        for action in commands:
            leaf = sub.add_parser(action)
            _shared(leaf)
            if action in ("show", "publish", "status", "compare", "sync"):
                leaf.add_argument("identity")
            if group == "checkpoint" and action == "create":
                leaf.add_argument("--config", default="{}")
                leaf.add_argument("--runner", choices=("serial", "async"), default="serial")
                leaf.add_argument("--description", required=True)
                leaf.add_argument("--parent")
                leaf.add_argument("--data", default="{}", help="public data fingerprint manifest JSON or @file")
            if action in ("create", "seed", "restore", "add") and group != "checkpoint":
                leaf.add_argument("--body", help="public JSON object or @file")
            if group == "family" and action == "create":
                leaf.add_argument("--family-id")
                leaf.add_argument("--max-sessions", type=int)
                leaf.add_argument("--practice-allowance", type=int, default=0)
                leaf.add_argument("--reserve", type=int, default=0)
            if group == "recommended":
                if action in ("seed", "restore"):
                    leaf.add_argument("--suite", default="d01-d02-sandbox-serial-v1")
                    leaf.add_argument("--checkpoint")
                    leaf.add_argument("--request-id")
                if action == "history":
                    leaf.add_argument("--suite")
            if group == "campaign" and action == "run":
                leaf.add_argument("--campaign-id")
                leaf.add_argument("--family")
                leaf.add_argument("--candidate")
                leaf.add_argument("--suite", default="d01-d02-sandbox-serial-v1")
                leaf.add_argument("--max-sessions", type=int)
                leaf.add_argument("--practice-allowance", type=int)
                leaf.add_argument("--reserve", type=int)
                leaf.add_argument("--seed", type=int, default=0)
                leaf.add_argument("--hypothesis")
                leaf.add_argument("--data-paths", default="{}")
            if group == "evidence":
                leaf.add_argument("--supplier")
                leaf.add_argument("--message", type=int)
                leaf.add_argument("--campaign")
                leaf.add_argument("--case")
            if group == "findings" and action == "list":
                leaf.add_argument("--campaign")
            if group == "campaign" and action == "reconcile":
                leaf.add_argument("identity")
                leaf.add_argument("--attempt", required=True)
                leaf.add_argument("--session", required=True)
    restore = groups.add_parser("restore")
    restore.set_defaults(loop_group="restore")
    _shared(restore)
    restore.add_argument("identity")
    restore.add_argument("--destination", type=Path, required=True)
    restore.add_argument("--data-paths", default="{}")


def public_json(value):
    if value is None:
        raise ValueError("JSON object required")
    body = json.loads(Path(value[1:]).read_text() if value.startswith("@") else value)
    if not isinstance(body, dict):
        raise ValueError("JSON object required")
    from .models import check_json

    check_json(body)
    return body


def _checkpoint(client, identity, root):
    try:
        return load_checkpoint(identity, root / "checkpoints")
    except FileNotFoundError:
        return client.read("checkpoints", identity)


def dispatch(args):
    group, action = args.loop_group, getattr(args, "loop_action", None)
    if group == "checkpoint" and action == "create":
        return create_checkpoint(
            args.repo,
            config=public_json(args.config),
            runner=args.runner,
            author=args.author,
            description=args.description,
            parent_id=args.parent,
            data=public_json(args.data),
            root=args.root / "checkpoints",
        )
    if (group == "checkpoint" and action == "show") or group == "restore":
        try:
            checkpoint = load_checkpoint(args.identity, args.root / "checkpoints")
        except FileNotFoundError:
            pass
        else:
            if group == "checkpoint":
                return checkpoint
            restored = restore_checkpoint(
                args.repo, checkpoint, args.destination, data_paths=public_json(args.data_paths)
            )
            return {"checkpoint_id": args.identity, "destination": str(restored)}
    client = LoopClient(args.url, os.environ.get("LAB_UPLOAD_TOKEN"))
    try:
        if group == "checkpoint":
            body = _checkpoint(client, args.identity, args.root)
            if action == "publish":
                body = publish_checkpoint(args.repo, body)
                _save(body, args.root / "checkpoints")
                return client.write("checkpoint", body)
            return body
        if group == "suite":
            if action == "create":
                return client.write("suite", public_json(args.body) if args.body else default_suite())
            return client.read("suites", getattr(args, "identity", None))
        if group == "family":
            if action == "show":
                return client.read("families", args.identity)
            body = (
                public_json(args.body)
                if args.body
                else dict(
                    family_id=args.family_id,
                    max_sessions=args.max_sessions,
                    practice_allowance=args.practice_allowance,
                    reserve=args.reserve,
                )
            )
            return client.write("family", body)
        if group == "recommended":
            if action == "show":
                return client.read("recommended", args.identity)
            if action == "history":
                body = client.read("history")
                return {
                    "history": [event for event in body["history"] if not args.suite or event["suite_id"] == args.suite]
                }
            body = (
                public_json(args.body)
                if args.body
                else dict(suite_id=args.suite, checkpoint_id=args.checkpoint, author=args.author)
            )
            if action == "seed":
                if args.request_id:
                    body["request_id"] = args.request_id
                return client.write("seed", body)
            body.setdefault("request_id", args.request_id or uuid.uuid4().hex)
            if "generation" not in body:
                prior = next(
                    (
                        event
                        for event in client.read("history").get("history", [])
                        if event["event_id"] == body["request_id"]
                    ),
                    None,
                )
                original = prior.get("request", {}) if prior else {}
                if (
                    prior
                    and prior["action"] == "restore"
                    and all(body.get(key) == original.get(key) for key in ("suite_id", "checkpoint_id", "author"))
                ):
                    body["generation"] = original["generation"]
                else:
                    body["generation"] = client.read("recommended", body["suite_id"])["generation"]
            return client.write("restore", body)
        if group == "restore":
            checkpoint = _checkpoint(client, args.identity, args.root)
            restored = restore_checkpoint(
                args.repo, checkpoint, args.destination, data_paths=public_json(args.data_paths)
            )
            return {"checkpoint_id": args.identity, "destination": str(restored)}
        if group == "campaign":
            if action == "run":
                identity = args.campaign_id
                if identity and (
                    (campaign_dir(args.root, identity) / "state.json").exists()
                    or (not args.family and not args.candidate and not args.hypothesis)
                ):
                    return run_campaign(client, identity, args.repo, args.root, data_paths=public_json(args.data_paths))
                if not args.family or not args.candidate or not args.hypothesis or args.max_sessions is None:
                    raise ValueError("new campaign requires family, candidate, hypothesis and max-sessions")
                suite = client.read("suites", args.suite)
                if args.max_sessions < suite["max_sessions"]:
                    raise ValueError("explicit campaign ceiling is below suite sessions")
                observed_quota = arena_snapshot(suite)
                family = next(
                    (
                        entry
                        for entry in client.read("families").get("families", [])
                        if entry["family_id"] == args.family
                    ),
                    None,
                )
                if family is None:
                    client.write(
                        "family",
                        dict(
                            family_id=args.family,
                            max_sessions=args.max_sessions,
                            practice_allowance=args.practice_allowance or 0,
                            reserve=args.reserve or 0,
                        ),
                    )
                elif any(
                    value is not None and value != family[key]
                    for key, value in (("practice_allowance", args.practice_allowance), ("reserve", args.reserve))
                ):
                    raise ValueError("campaign flags conflict with immutable family protections")
                current = client.read("recommended", args.suite)
                body = dict(
                    campaign_id=identity or uuid.uuid4().hex,
                    family_id=args.family,
                    suite_id=args.suite,
                    baseline_id=current["checkpoint_id"],
                    candidate_id=args.candidate,
                    generation=current["generation"],
                    seed=args.seed,
                    author=args.author,
                    hypothesis=args.hypothesis,
                    quota=observed_quota,
                )
                campaign = client.write("campaign", body)
                return run_campaign(
                    client, campaign["campaign_id"], args.repo, args.root, data_paths=public_json(args.data_paths)
                )
            if action == "sync":
                return sync_campaign(client, args.identity, args.root)
            if action == "reconcile":
                return reconcile_attempt(client, args.identity, args.attempt, args.session)
            body = client.read("campaigns", args.identity)
            if action == "status":
                blockers = [
                    attempt["attempt_id"]
                    for attempt in body["attempts"]
                    if attempt["status"] == "started"
                    or (
                        "start" in attempt
                        and not attempt.get("reconciliation")
                        and not attempt.get("not_created")
                        and attempt.get("result", {}).get("ended") is not True
                    )
                ]
                body["blocking_attempts"] = blockers
                body["next_action"] = (
                    "Verify owned ended session and campaign reconcile explicit attempt/session IDs"
                    if blockers
                    else "Sync saved results or resume only never-started pending cells"
                    if any(a["status"] == "pending" for a in body["attempts"])
                    else None
                )
                return body
            suite = client.read("suites", body["suite_id"])
            return evaluate_campaign(
                suite,
                client.read("checkpoints", body["baseline_id"]),
                client.read("checkpoints", body["candidate_id"]),
                body["attempts"],
            )
        if group == "evidence":
            body = client.read("evidence", args.identity)
            if args.campaign and body["campaign_id"] != args.campaign:
                raise ValueError("evidence campaign mismatch")
            attempt = body["attempt"]
            if args.case and attempt["case_id"] != args.case:
                raise ValueError("evidence case mismatch")
            if args.message is not None and not args.supplier:
                raise ValueError("message selection requires supplier")
            if args.supplier:
                if args.supplier not in attempt.get("threads", {}):
                    raise ValueError("supplier evidence unavailable")
                thread = attempt["threads"][args.supplier]
                if args.message is not None:
                    messages = thread if isinstance(thread, list) else thread.get("messages", thread.get("events", []))
                    if args.message < 0 or args.message >= len(messages):
                        raise ValueError("message evidence unavailable")
                    if isinstance(thread, list):
                        thread = [messages[args.message]]
                    else:
                        key = "messages" if "messages" in thread else "events"
                        thread = {**thread, key: [messages[args.message]]}
                attempt["threads"] = {args.supplier: thread}
                body["selection"] = {"supplier": args.supplier, "message_index": args.message}
            return body
        if group == "findings":
            if action == "add":
                return client.write("finding", public_json(args.body))
            body = client.read("findings")
            if args.campaign:
                body["findings"] = [finding for finding in body["findings"] if finding["campaign_id"] == args.campaign]
            return body
        raise ValueError("unknown command")
    finally:
        if hasattr(client, "close"):
            client.close()


def handle_loop(args):
    try:
        body = dispatch(args)
        incomplete = (
            args.loop_group == "campaign" and args.loop_action in ("run", "sync") and not body.get("completion")
        )
        output = {"schema_version": 1, **body}
        if incomplete:
            output["execution_status"] = "blocked" if body.get("blocking_attempts") else "incomplete"

        if args.format == "markdown":
            from .reports import markdown_report

            print(markdown_report(output), end="")
        else:
            print(json.dumps(output, allow_nan=False))
        return 1 if incomplete else 0
    except LoopError as error:
        code, message, exit_code = error.code, str(error), 1
    except KeyboardInterrupt:
        code, message, exit_code = "interrupted", "Interrupted; inspect local state and sync before resuming", 130
    except ValueError as error:
        code, message, exit_code = "invalid_input", "Invalid input or unavailable local checkpoint dependencies", 2
        safe_messages = (
            "checkpoint locked dependencies unavailable",
            "checkpoint runtime/data preflight failed",
            "required data mapping missing",
            "required data missing or hash mismatch",
            "campaign worker is active",
            "campaign already running locally",
            "arena open-session limit reached",
            "authoritative practice quota unavailable",
            "ARENA_API_KEY required before campaign execution",
            "campaign flags conflict with immutable family protections",
            "explicit campaign ceiling is below suite sessions",
        )
        if type(error) is ValueError and str(error).startswith(safe_messages):
            message = str(error)
    except Exception:
        code, message, exit_code = "operation_failed", "Operation failed; inspect saved local campaign state", 1
    print(json.dumps({"schema_version": 1, "error": {"code": code, "message": message}}))
    return exit_code


def main(argv=None):
    load_env()
    parser = Parser(prog="negotiator lab loop")
    configure(parser)
    try:
        return handle_loop(parser.parse_args(argv))
    except ValueError:
        print(
            json.dumps(
                {"schema_version": 1, "error": {"code": "invalid_input", "message": "Invalid command arguments"}}
            )
        )
        return 2
"""Host setup, experiment execution, recovery sync and read-only history import."""

import argparse
import getpass
import json
import os
import secrets
import sys
from pathlib import Path

from arena_kit.cli import load_env
from arena_kit.client import ArenaClient
from dotenv import dotenv_values

from .history import import_history
from .publish import Publisher, sync
from .runner import agent_factory, capture_provenance, plan_run, run_experiment
from .server import DashboardServer
from .store import Store


def _publisher() -> Publisher | None:
    url, token = os.environ.get("LAB_URL"), os.environ.get("LAB_UPLOAD_TOKEN")
    if bool(url) != bool(token):
        raise ValueError("set both LAB_URL and LAB_UPLOAD_TOKEN, or neither for local buffering")
    return Publisher(url, token) if url and token else None


def _author(value):
    return value or os.environ.get("LAB_AUTHOR") or getpass.getuser()


def _init(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "w") as stream:
        stream.write(f"LAB_PASSWORD=REDACTED")
        stream.flush()
        os.fsync(stream.fileno())
    print(path)


def _env_flag(name: str, default: bool = False) -> bool:
    value = os.environ.get(name)
    if value is None:
        return default
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"{name} must be a boolean")


def parser():
    ap = argparse.ArgumentParser(prog="negotiator lab", description="Shared experiment dashboard tooling")
    sub = ap.add_subparsers(dest="command", required=True)
    init = sub.add_parser("init", help="generate host secrets without printing values")
    init.add_argument("--secrets-file", type=Path, default=Path(".lab-secrets.env"))
    serve = sub.add_parser("serve", help="serve the authenticated dashboard")
    serve.add_argument("--host", default=os.environ.get("LAB_HOST", "127.0.0.1"))
    serve.add_argument("--port", type=int, default=os.environ.get("PORT", os.environ.get("LAB_PORT", "8000")))
    serve.add_argument("--db", type=Path, default=os.environ.get("LAB_DB", "experiments/dashboard.sqlite3"))
    serve.add_argument("--secrets-file", type=Path, default=os.environ.get("LAB_SECRETS_FILE", ".lab-secrets.env"))
    serve.add_argument(
        "--secure-cookies",
        action=argparse.BooleanOptionalAction,
        default=None,
        help="require HTTPS for browser authentication cookies",
    )
    run = sub.add_parser("run", help="run an explicit serial case plan")
    run.add_argument("--name", required=True)
    run.add_argument("--hypothesis", required=True)
    run.add_argument("--author")
    run.add_argument("--agent", default="package")
    run.add_argument("--config", default="{}", help="JSON object passed as factory keyword arguments")
    run.add_argument("--cases", nargs="+", required=True)
    run.add_argument("--repetitions", type=int, required=True)
    run.add_argument("--max-sessions", type=int, required=True)
    run.add_argument("--environment", choices=["simulator", "sandbox", "practice"], required=True)
    run.add_argument(
        "--release",
        type=Path,
        default=Path(os.environ["ARENA_RELEASE"]) if os.environ.get("ARENA_RELEASE") else None,
        help="overlay directory included in the combined data fingerprint",
    )
    run.add_argument("--baseline", dest="baseline_id")
    run.add_argument("--allow-dirty", action="store_true")
    run.add_argument("--root", type=Path, default=Path("experiments/runs"))
    run.add_argument("--repo", type=Path, default=Path.cwd())
    run.add_argument("--data", type=Path, default=Path(os.environ.get("ARENA_DATA", "data/package")))
    recover = sub.add_parser("sync", help="retry saved snapshot uploads")
    recover.add_argument("--root", type=Path, default=Path("experiments/runs"))
    history = sub.add_parser("import", help="read only owned practice/sandbox session history")
    history.add_argument("--environment", choices=["practice", "sandbox"], required=True)
    history.add_argument("--root", type=Path, default=Path("experiments/runs"))
    history.add_argument("--author")
    history.add_argument(
        "--db",
        type=Path,
        default=Path("experiments/dashboard.sqlite3"),
        help="consult existing host runs and save imports directly when this DB exists",
    )
    from .loop_cli import add_loop_commands, configure

    add_loop_commands(sub)
    configure(groups=sub)
    return ap


def parse_args(argv):
    args = parser().parse_args(argv)
    if args.command == "serve" and args.secure_cookies is None:
        args.secure_cookies = _env_flag("LAB_SECURE_COOKIES")
    return args


def main(argv=None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if argv and argv[0] == "loop":
        from .loop_cli import main as loop_main

        return loop_main(argv[1:])
    if argv and argv[0] in (
        "checkpoint",
        "suite",
        "family",
        "recommended",
        "campaign",
        "evidence",
        "findings",
        "restore",
    ):
        from .loop_cli import main as loop_main

        return loop_main(argv)
    try:
        load_env()
        args = parse_args(argv)
        if args.command == "init":
            _init(args.secrets_file)
            return 0
        if args.command == "serve":
            if os.name == "posix" and args.secrets_file.is_file() and args.secrets_file.stat().st_mode & 0o077:
                raise ValueError("host secret file must have mode 0600")
            values = dotenv_values(args.secrets_file)
            REDACTED = os.environ.get("LAB_PASSWORD") or values.get("LAB_PASSWORD")
            token = os.environ.get("LAB_UPLOAD_TOKEN") or values.get("LAB_UPLOAD_TOKEN")
            with DashboardServer(
                (args.host, args.port),
                Store(args.db),
                REDACTED=REDACTED,
                upload_token=token,
                secure_cookie=args.secure_cookies,
            ) as server:
                print(f"Dashboard: http://{args.host}:{server.server_port}", flush=True)
                try:
                    server.serve_forever()
                except KeyboardInterrupt:
                    pass
            return 0
        if args.command == "sync":
            url, token = os.environ.get("LAB_URL"), os.environ.get("LAB_UPLOAD_TOKEN")
            if not url or not token:
                raise ValueError("sync requires LAB_URL and LAB_UPLOAD_TOKEN")
            report = sync(args.root, url, token)
            print(json.dumps(report))
            return 0 if report["failed"] == 0 else 1
        arena_url = os.environ.get("ARENA_URL", "https://arena.tacto.ai")
        if args.command == "run":
            config = json.loads(args.config)
            if not isinstance(config, dict):
                raise ValueError("agent config must be a JSON object")
            provenance, patch = capture_provenance(
                args.repo, data_dir=args.data, release_dir=args.release, allow_dirty=args.allow_dirty
            )
            run = plan_run(
                name=args.name,
                author=_author(args.author),
                hypothesis=args.hypothesis,
                agent=args.agent,
                config=config,
                cases=args.cases,
                repetitions=args.repetitions,
                max_sessions=args.max_sessions,
                environment=args.environment,
                arena_url=arena_url,
                provenance=provenance,
                baseline_id=args.baseline_id,
            )
            factory = agent_factory(args.agent, config)
            publisher = _publisher()
            from .transport import JournaledArena

            client = JournaledArena(args.root / run.run_id / "serial.jsonl", base_url=arena_url, rate=2)
            try:
                final = run_experiment(run, args.root, client, factory, publisher=publisher, patch=patch)
            finally:
                client.http.close()
            print(f"{final.status}: {args.root / final.run_id / 'run.json'}")
            if final.quota:
                print(f"practice sessions left: {final.quota.left}/{final.quota.limit}")
            return 0 if final.status == "completed" else 130 if final.status == "interrupted" else 1
        client = ArenaClient(base_url=arena_url, rate=1)
        try:
            report = import_history(
                client,
                args.root,
                environment=args.environment,
                arena_url=arena_url,
                author=_author(args.author),
                store=Store(args.db) if args.db.is_file() else None,
                publisher=_publisher(),
            )
        finally:
            client.http.close()
        print(json.dumps(report))
        return 0 if report["failed"] == 0 else 1
    except FileExistsError:
        print("lab: secret file already exists", file=sys.stderr)
    except ValueError as error:
        # Only our validation messages are printed; Pydantic and JSON errors echo input values.
        message = (
            str(error) if type(error) is ValueError and error.__class__.__module__ == "builtins" else "invalid input"
        )
        allowed = (
            "working tree is dirty",
            "set both LAB_URL",
            "sync requires",
            "host secret file",
            "agent config must",
            "case/repetition plan",
            "configuration contains",
            "agent must",
            "dashboard REDACTED",
            "simulator",
        )
        print("lab: " + (message if message.startswith(allowed) else "invalid input"), file=sys.stderr)
    except KeyboardInterrupt:
        return 130
    except Exception:
        print("lab: operation failed; check configuration and saved local snapshots", file=sys.stderr)
    return 2
